Definition sp_off_chk (e : expr) : bool :=
  match e with EAlu ALU_ADD (EVar 0) (ELit c) => (Z.leb (-2560) c && Z.leb c 0)%bool | _ => false end.

Lemma sp_off_val : forall E e, sp_off_chk e = true ->
  (ASP_LO <= bv_unsigned (ev E 0))%Z -> (bv_unsigned (ev E 0) <= ASP_HI)%Z ->
